[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "<div class="print-heading">				<h2></h2></div>"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "{#- ============================================================
    Quality Inspection - Custom Print Format (Frappe/ERPNext v16)
    Print Format Type : Jinja  |  Doctype : Quality Inspection
    Page Size         : A4 | Margins T/B 12mm, L/R 10mm

    >>> EDIT THE FIELD MAP BELOW to match your actual custom
        fieldnames (check Customize Form > Quality Inspection).
        Nothing else needs changing.
    ============================================================ -#}

{%- set F = {
      'customer'    : 'custom_customer_name',
      'po_no'       : 'custom_po_no',
      'po_date'     : 'custom_po_date',
      'msn_no'      : 'custom_msn_no',
      'job_no'      : 'custom_job_no',
      'item_desc'   : 'custom_item_description',
      'drawing_no'  : 'custom_drawing_no',
      'drawing_rev' : 'custom_revision',
      'acceptance'  : 'custom_acceptance_code',
      'diagram'     : 'custom_diagram'
    } -%}

{#- Section titles for the dynamic readings table -#}
{%- set TITLE_PAIRED = 'Thickness Readings (mm)' -%}   {#- used when the grid has exactly 2 columns -#}
{%- set TITLE_TABLE  = 'Inspection & Test Plan' -%}    {#- used when the grid has 3+ columns -#}

{#- ---------- header / order fields (read defensively) ---------- -#}
{%- set vCustomer = doc.get(F.customer)    or '' -%}
{%- set vPoNo     = doc.get(F.po_no)       or '' -%}
{%- set vPoDate   = doc.get(F.po_date)     or '' -%}
{%- set vMsn      = doc.get(F.msn_no)      or '' -%}
{%- set vJob      = doc.get(F.job_no)      or '' -%}
{%- set vItemDesc = (doc.get(F.item_desc) or doc.description or '') | string | trim -%}
{%- if vItemDesc in ['.', '-'] -%}{%- set vItemDesc = '' -%}{%- endif -%}
{%- set vDrgNo    = doc.get(F.drawing_no)  or '' -%}
{%- set vDrgRev   = doc.get(F.drawing_rev) or '' -%}
{%- set vAccept   = doc.get(F.acceptance)  or '' -%}
{%- set vTitle    = doc.get('custom_title') or 'Quality Inspection Report' -%}

{%- set vDrawing = vDrgNo ~ (' / Rev. ' ~ vDrgRev if vDrgNo and vDrgRev else vDrgRev) -%}

{#- ============================================================
    IMAGE RESOLUTION — Diagrams gallery
    Matches the "diagram image gallery" client script exactly:
    File records attached to this document, tagged
    attached_to_field == 'custom_diagram', image extensions only,
    ordered by creation ascending (upload order). Untagged sidebar
    attachments are intentionally excluded, same as the client script.
    ============================================================ -#}
{%- set GALLERY_FIELD = F.diagram -%}
{%- set IMG_EXT = ('.png', '.jpg', '.jpeg', '.gif', '.webp') -%}

{%- set diagram_files = frappe.get_all('File',
      filters={'attached_to_doctype': doc.doctype,
               'attached_to_name': doc.name,
               'attached_to_field': GALLERY_FIELD,
               'is_folder': 0},
      fields=['file_url', 'file_name'],
      order_by='creation asc') -%}

{%- set diagrams = [] -%}
{%- for f in diagram_files -%}
  {%- set u = (f.file_url or '') | string -%}
  {%- if (u.split('?')[0] | lower).endswith(IMG_EXT) -%}
    {%- set imgPath = u.split('?')[0] -%}
    {%- if u.startswith('http://') or u.startswith('https://') or u.startswith('data:') or imgPath.startswith('/private/') -%}
      {#- Private files: keep the file_url EXACTLY as stored. Frappe's PDF
          pipeline (frappe.utils.pdf.inline_private_images) looks the File up
          by exact file_url and embeds it as base64; URL-encoding spaces
          breaks that lookup. -#}
      {%- set _ = diagrams.append(u) -%}
    {%- else -%}
      {#- Public files: URL-encode so spaces/brackets in filenames don't
          break loading. -#}
      {%- set _ = diagrams.append(imgPath | urlencode) -%}
    {%- endif -%}
  {%- endif -%}
{%- endfor -%}

{#- ============================================================
    READINGS GRID (custom JSON grid) - fully dynamic
    ============================================================ -#}
{%- set rcfg  = json.loads(doc.get('custom_custom_readings') or '{}') -%}
{%- set rdata = json.loads(doc.get('custom_custom_readings_data') or '{}') -%}
{%- set vcols = [] -%}
{%- for c in (rcfg.get('columns') or []) -%}
  {%- if not c.get('hidden') -%}{%- set _ = vcols.append(c) -%}{%- endif -%}
{%- endfor -%}
{%- set rrows = rdata.get('rows') or [] -%}
{%- set ncols = vcols | length -%}

{#- columns whose values are all short (Sr no, P/R/W, etc.) get centred + tight -#}
{%- set narrow = [] -%}
{%- for c in vcols -%}
  {%- set m = namespace(n=0) -%}
  {%- for r in rrows -%}
    {%- set l = (r.get(c['id']) or '') | string | trim | length -%}
    {%- if l > m.n -%}{%- set m.n = l -%}{%- endif -%}
  {%- endfor -%}
  {%- if m.n <= 4 -%}{%- set _ = narrow.append(c['id']) -%}{%- endif -%}
{%- endfor -%}

{#- paired layout (2-column grids only), filled column-wise across 3 pairs -#}
{%- set pairs  = 3 -%}
{%- set percol = ((rrows | length) / pairs) | round(0, 'ceil') | int -%}
{%- set kSr    = vcols[0]['id'] if ncols > 0 else '' -%}
{%- set kVal   = vcols[1]['id'] if ncols > 1 else '' -%}
{%- set lblSr  = vcols[0]['label'] if ncols > 0 else 'SR.NO.' -%}
{%- set lblVal = vcols[1]['label'] if ncols > 1 else 'VALUE' -%}

{#- ============================================================
    CERTIFICATE GRID
    ============================================================ -#}
{%- set ccfg  = json.loads(doc.get('custom_certificates') or '{}') -%}
{%- set cdata = json.loads(doc.get('custom_certificates_data') or '{}') -%}
{%- set ccols = ccfg.get('columns') or [] -%}
{%- set crows_all = cdata.get('rows') or [] -%}
{%- set kCn = ccols[0]['id'] if ccols | length > 0 else '' -%}
{%- set kCv = ccols[1]['id'] if ccols | length > 1 else '' -%}

{#- MSN is a header field, so drop the duplicate row from the certificate block -#}
{%- set skip_certs = [] -%}
{%- if vMsn -%}{%- set _ = skip_certs.append('MSN NO.') -%}{%- endif -%}
{%- set crows = [] -%}
{%- if kCn -%}
  {%- for r in crows_all -%}
    {%- if (r.get(kCn) or '') | string | trim | upper not in skip_certs -%}
      {%- set _ = crows.append(r) -%}
    {%- endif -%}
  {%- endfor -%}
{%- endif -%}
{%- set chalf = ((crows | length) / 2) | round(0, 'ceil') | int -%}

<style>
  .qi { font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
        color: #16181c; font-size: 9pt; line-height: 1.3; }
  .qi table { border-collapse: collapse; width: 100%; }
  .qi td, .qi th { vertical-align: top; }

  .qi-top { border-bottom: 2px solid #16181c; padding-bottom: 5px; margin-bottom: 9px; }
  .qi-top h1 { font-size: 14pt; font-weight: 700; letter-spacing: .3px; margin: 0; }
  .qi-top .sub { font-size: 8.5pt; color: #5a6170; margin-top: 2px; }

  .qi-meta td { border: 1px solid #d3d7de; padding: 4px 7px; }
  .qi-meta td.k { background: #f4f5f7; color: #4b5261; width: 15%;
                  font-size: 8pt; font-weight: 600; white-space: nowrap; }
  .qi-meta td.v { width: 35%; font-weight: 500; }

  .qi-sec { font-size: 8.5pt; font-weight: 700; letter-spacing: .5px;
            border-bottom: 1px solid #16181c; padding-bottom: 2px; margin: 12px 0 6px; }

  .qi-fig { text-align: center; border: 1px solid #d3d7de; padding: 6px; }
  .qi-fig img { display: inline-block; max-width: 100%; max-height: 260px;
                width: auto; height: auto; }

  /* multi-image diagrams gallery */
  .qi-gallery { width: 100%; border-collapse: collapse; }
  .qi-gallery td { border: 1px solid #d3d7de; padding: 6px; text-align: center;
                   vertical-align: middle; width: 50%; }
  .qi-gallery img { display: inline-block; max-width: 100%; max-height: 320px;
                     width: auto; height: auto; }

  /* paired readings (2-column grids) */
  .qi-rd th { background: #eceef1; border: 1px solid #c8ccd4; padding: 4px 7px;
              font-size: 8pt; font-weight: 700; text-align: left; }
  .qi-rd th.n { text-align: right; }
  .qi-rd td { border: 1px solid #d3d7de; padding: 4px 7px; height: 14pt; }
  .qi-rd td.sr { color: #4b5261; width: 10%; }
  .qi-rd td.n  { width: 23.3%; text-align: right; font-weight: 600;
                 font-variant-numeric: tabular-nums; }
  .qi-rd td.gap, .qi-rd th.gap { border: none; width: 1.2%; padding: 0; }

  /* full grid (3+ columns) */
  .qi-grid { font-size: 7.6pt; }
  .qi-grid thead { display: table-header-group; }
  .qi-grid tr { page-break-inside: avoid; }
  .qi-grid th { background: #eceef1; border: 1px solid #c8ccd4; padding: 4px 5px;
                font-size: 7.2pt; font-weight: 700; text-align: left;
                vertical-align: bottom; }
  .qi-grid td { border: 1px solid #d3d7de; padding: 4px 5px;
                word-wrap: break-word; }
  .qi-grid th.c, .qi-grid td.c { text-align: center; width: 1%; }
  .qi-grid td.c { white-space: nowrap; }
  .qi-grid tr.hd td { background: #f4f5f7; font-weight: 700; }

  .qi-cert td { border: 1px solid #d3d7de; padding: 4px 7px; }
  .qi-cert td.k { background: #f4f5f7; color: #4b5261; font-size: 8pt;
                  font-weight: 600; width: 42%; }

  .qi-rem { border: 1px solid #d3d7de; padding: 6px 8px; min-height: 30px; }
  .qi-sign td.line { padding: 26px 8px 3px; border-bottom: 1px solid #16181c; width: 40%; }
  .qi-sign td.line .who { font-weight: 600; font-size: 9pt; }
  .qi-cap { font-size: 7.5pt; color: #7a8290; padding-top: 3px; width: 40%; }

  @media print {
    .qi { font-size: 8.6pt; }
    .qi-fig img { max-height: 230px; }
    .qi-meta, .qi-rd, .qi-cert, .qi-sign, .qi-fig { page-break-inside: avoid; }
    .qi-gallery tr { page-break-inside: avoid; }
  }
</style>

<div class="qi">

  <div class="qi-top">
    <h1>{{ vTitle }}</h1>
    <div class="sub">{{ doc.name }} &nbsp;|&nbsp; {{ doc.company or '' }}</div>
  </div>

  {#- ---------- Customer & order details ---------- -#}
  <div class="qi-sec">Customer &amp; Order Details</div>
  <table class="qi-meta">
    <tr>
      <td class="k">Customer Name</td><td class="v">{{ vCustomer }}</td>
      <td class="k">Job No.</td><td class="v">{{ vJob }}</td>
    </tr>
    <tr>
      <td class="k">PO No.</td><td class="v">{{ vPoNo }}</td>
      <td class="k">PO Date</td>
      <td class="v">{% if vPoDate %}{{ frappe.utils.formatdate(vPoDate) }}{% endif %}</td>
    </tr>
    <tr>
      <td class="k">MSN No.</td><td class="v">{{ vMsn }}</td>
      <td class="k">Drawing No. &amp; Rev.</td><td class="v">{{ vDrawing }}</td>
    </tr>
    <tr>
      <td class="k">Acceptance Code</td><td class="v">{{ vAccept }}</td>
      <td class="k">Reference</td>
      <td class="v">{{ doc.reference_type or '' }}{% if doc.reference_name %} &mdash; {{ doc.reference_name }}{% endif %}</td>
    </tr>
  </table>

  {#- ---------- Item & inspection details ---------- -#}
  <div class="qi-sec">Item &amp; Inspection Details</div>
  <table class="qi-meta">
    <tr>
      <td class="k">Item Code</td><td class="v">{{ doc.item_code or '' }}</td>
      <td class="k">Inspection Type</td><td class="v">{{ doc.inspection_type or '' }}</td>
    </tr>
    <tr>
      <td class="k">Item Name</td><td class="v" colspan="3">{{ doc.item_name or '' }}</td>
    </tr>
    {% if vItemDesc %}
    <tr>
      <td class="k">Item Description</td><td class="v" colspan="3">{{ vItemDesc }}</td>
    </tr>
    {% endif %}
    <tr>
      <td class="k">Report Date</td>
      <td class="v">{% if doc.report_date %}{{ frappe.utils.formatdate(doc.report_date) }}{% endif %}</td>
      <td class="k">Status</td><td class="v">{{ doc.status or '' }}</td>
    </tr>
    <tr>
      <td class="k">Sample Size</td><td class="v">{{ doc.sample_size or 0 }}</td>
      <td class="k">Inspected By</td><td class="v">{{ doc.inspected_by or '' }}</td>
    </tr>
    {% if doc.verified_by %}
    <tr>
      <td class="k">Verified By</td><td class="v" colspan="3">{{ doc.verified_by }}</td>
    </tr>
    {% endif %}
  </table>

  {% if crows %}
  <div class="qi-sec">Mill Certificate &amp; Traceability</div>
  <table><tr>
    <td style="width:49.5%; padding-right:1%;">
      <table class="qi-cert">
        {% for r in crows %}{% if loop.index0 < chalf %}
        <tr><td class="k">{{ r.get(kCn) or '' }}</td><td>{{ r.get(kCv) or '' }}</td></tr>
        {% endif %}{% endfor %}
      </table>
    </td>
    <td style="width:49.5%;">
      <table class="qi-cert">
        {% for r in crows %}{% if loop.index0 >= chalf %}
        <tr><td class="k">{{ r.get(kCn) or '' }}</td><td>{{ r.get(kCv) or '' }}</td></tr>
        {% endif %}{% endfor %}
      </table>
    </td>
  </tr></table>
  {% endif %}

  {% if diagrams | length == 1 %}
  <div class="qi-sec">Diagrams</div>
  <div class="qi-fig">
    <img src="{{ diagrams[0] }}" alt="Inspection diagram">
  </div>
  {% elif diagrams | length > 1 %}
  {#- 2 images per row (larger images), wraps to additional rows as needed -#}
  {%- set per_row = 2 -%}
  {%- set n_rows = ((diagrams | length) / per_row) | round(0, 'ceil') | int -%}
  <div class="qi-sec">Diagrams</div>
  <table class="qi-gallery">
    {% for r in range(n_rows) %}
    <tr>
      {% for c in range(per_row) %}
        {% set idx = r * per_row + c %}
        <td>{% if idx < diagrams | length %}<img src="{{ diagrams[idx] }}" alt="Inspection diagram {{ idx + 1 }}">{% endif %}</td>
      {% endfor %}
    </tr>
    {% endfor %}
  </table>
  {% endif %}

  {% if rrows and ncols == 2 %}
  {#- ---------- paired layout: SR / VALUE x 3 ---------- -#}
  <div class="qi-sec">{{ TITLE_PAIRED }}</div>
  <table class="qi-rd">
    <tr>
      {% for c in range(pairs) %}
        {% if c > 0 %}<th class="gap"></th>{% endif %}
        <th>{{ lblSr }}</th><th class="n">{{ lblVal }}</th>
      {% endfor %}
    </tr>
    {% for i in range(percol) %}
    <tr>
      {% for c in range(pairs) %}
        {% if c > 0 %}<td class="gap"></td>{% endif %}
        {% set idx = c * percol + i %}
        {% if idx < rrows | length %}
          <td class="sr">{{ rrows[idx].get(kSr) or '' }}</td>
          <td class="n">{{ rrows[idx].get(kVal) or '' }}</td>
        {% else %}
          <td class="sr">&nbsp;</td><td class="n">&nbsp;</td>
        {% endif %}
      {% endfor %}
    </tr>
    {% endfor %}
  </table>

  {% elif rrows and ncols > 2 %}
  {#- ---------- full grid: every visible column ---------- -#}
  <div class="qi-sec">{{ TITLE_TABLE }}</div>
  <table class="qi-grid">
    <thead>
      <tr>
        {% for c in vcols %}
        <th class="{{ 'c' if c['id'] in narrow else '' }}">{{ c.get('label') or '' }}</th>
        {% endfor %}
      </tr>
    </thead>
    <tbody>
      {% for r in rrows %}
        {%- set hs = namespace(extra=0) -%}
        {%- for c in vcols[2:] -%}
          {%- if (r.get(c['id']) or '') | string | trim -%}{%- set hs.extra = hs.extra + 1 -%}{%- endif -%}
        {%- endfor -%}
        {% if hs.extra == 0 %}
        {#- heading row (e.g. "1  REVIEW OF DOCUMENTS") spans the grid -#}
        <tr class="hd">
          <td class="c">{{ r.get(vcols[0]['id']) or '' }}</td>
          <td colspan="{{ ncols - 1 }}">{{ r.get(vcols[1]['id']) or '' }}</td>
        </tr>
        {% else %}
        <tr>
          {% for c in vcols %}
          <td class="{{ 'c' if c['id'] in narrow else '' }}">{{ r.get(c['id']) or '' }}</td>
          {% endfor %}
        </tr>
        {% endif %}
      {% endfor %}
    </tbody>
  </table>
  {% endif %}

  <div class="qi-sec">Remarks</div>
  <div class="qi-rem">{{ doc.remarks or '&mdash;' }}</div>

  <table class="qi-sign" style="margin-top:16px;">
    <tr>
      <td class="line"><div class="who">{{ doc.inspected_by or '' }}</div></td>
      <td style="width:20%;"></td>
      <td class="line"><div class="who">{{ doc.verified_by or '' }}</div></td>
    </tr>
    <tr>
      <td class="qi-cap">Inspected by</td>
      <td></td>
      <td class="qi-cap">Verified by</td>
    </tr>
  </table>

</div>"}]
